local function demon(ctx,e)for _,tag in ipairs(ctx:card_definition(ctx:entity(e).card_id).tags)do if tag=="demon" or tag=="all"then return true end end return false end
return {api_version=1,id="NEW1_003",name="Sacrificial Pact",text="Destroy a friendly Demon. Restore #5 Health to your hero.",set="LEGACY",type="spell",class="warlock",spell_school="shadow",cost=0,target_mode="required",targets=function(ctx,self)local r={};for _,e in ipairs(ctx:friendly_minions(self))do if demon(ctx,e)then r[#r+1]=e end end;return r end,on_play=function(ctx,self,target)local p=ctx:controller(self);cardlib.effects.destroy(ctx, target);cardlib.effects.heal(ctx, ctx:player(p).hero,5)end}
